from pysat.solvers import Glucose3
import itertools

n = 20
solver = Glucose3()

edge_vars = {}
var_idx = 1
for i in range(n):
    for j in range(i + 1, n):
        edge_vars[(i, j)] = var_idx
        var_idx += 1

def edge_var(i, j):
    if i > j:
        i, j = j, i
    return edge_vars[(i, j)]

# No red K_5 (color 0)
for clique in itertools.combinations(range(n), 5):
    clause = []
    for i, j in itertools.combinations(clique, 2):
        clause.append(edge_var(i, j))
    solver.add_clause(clause)

# No blue K_4 (color 1)
for clique in itertools.combinations(range(n), 4):
    clause = []
    for i, j in itertools.combinations(clique, 2):
        clause.append(-edge_var(i, j))
    solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    colors = []
    for i in range(n):
        for j in range(i + 1, n):
            var = edge_var(i, j)
            colors.append(1 if model[var - 1] > 0 else 0)
    print(colors)
else:
    print("UNSAT")

